import sys
from typing import List, Tuple

def min_day_to_take_last_exam(n: int, exams: List[Tuple[int, int]]) -> int:
    exams.sort(key=lambda x: (-x[1], x[0]))
    current_day = 0
    last_taken = 0

    for schedule_day, early_day in exams:
        if current_day < early_day:
            current_day = early_day
        elif current_day > schedule_day:
            current_day = schedule_day

        if current_day >= last_taken:
            last_taken = current_day + 1
        else:
            current_day = last_taken
            last_taken = current_day + 1

    return last_taken - 1

def main():
    n = int(sys.stdin.readline().strip())
    exams = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]
    result = min_day_to_take_last_exam(n, exams)
    print(result)

if __name__ == "__main__":
    main()

def find_min_day_for_last_exam(n, exams):
    exams.sort(key=lambda x: (x[1], x[0]))

    last_day = 0
    for schedule_day, early_day in exams:
        if early_day > last_day:
            last_day = early_day
        else:
            last_day += 1

    return last_day

